class Solution { fun earliestSecondToMarkIndices(nums:IntArray,changeIndices:IntArray):Int{var base=nums.size.toLong();for(value in nums)base+=value;fun canFinish(seconds:Int):Boolean{val first=IntArray(nums.size){-1};for(time in seconds-1 downTo 0)first[changeIndices[time]-1]=time;val chosen=java.util.PriorityQueue<Int>();var available=0;var saved=0L;for(time in seconds-1 downTo 0){val index=changeIndices[time]-1;val value=nums[index];if(time==first[index]&&value>1){if(available>0){available--;chosen.add(value);saved+=value-1L}else if(chosen.isNotEmpty()&&chosen.peek()<value){val removed=chosen.poll();saved-=removed-1L;available++;chosen.add(value);saved+=value-1L}else available++}else available++};return base-saved<=seconds};var left=1;var right=changeIndices.size+1;while(left<right){val middle=(left+right)/2;if(canFinish(middle))right=middle else left=middle+1};return if(left==changeIndices.size+1)-1 else left} }
